module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [3:0];
reg [2:0] SP;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 4;
        EMPTY <= 1;
        FULL <= 0;
        dataOut <= 0;
        for (integer i = 0; i < 4; i = i + 1) begin
            stack_mem[i] <= 0;
        end
    end else if (EN) begin
        if (SP != 0 && !FULL) begin
            SP <= SP - 1;
            dataOut <= stack_mem[SP];
            if (SP == 3)
                EMPTY <= 0;
        end else if (SP != 4 && !EMPTY) begin
            stack_mem[SP] <= dataIn;
            SP <= SP + 1;
            if (SP == 0)
                FULL <= 1;
        end
    end
end

endmodule
